css:
.warehouse-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce3ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.warehouse-sim-container .warehouse-sim-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: white;
    padding: 30px;
    border-radius: 16px;
    margin-bottom: 24px;
    box-shadow: 0 8px 20px rgba(26,58,92,0.25);
    text-align: center;
}

.warehouse-sim-container .warehouse-sim-header h1 {
    margin: 0 0 6px 0;
    font-size: 1.8rem;
}

.warehouse-sim-container .warehouse-sim-header p {
    margin: 0;
    opacity: 0.85;
    font-size: 1.05rem;
}

.warehouse-sim-container .warehouse-sim-period-counter {
    text-align: center;
    font-size: 1.15rem;
    font-weight: 600;
    color: #1a3a5c;
    margin-bottom: 20px;
}

.warehouse-sim-container .warehouse-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(155px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}

.warehouse-sim-container .warehouse-sim-status-card {
    background: white;
    border-radius: 12px;
    padding: 18px 14px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.25s ease;
}

.warehouse-sim-container .warehouse-sim-status-card:hover {
    transform: translateY(-4px);
}

.warehouse-sim-container .warehouse-sim-label {
    color: #667;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.warehouse-sim-container .warehouse-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #1a3a5c;
}

.warehouse-sim-container .warehouse-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.06);
    border-left: 5px solid #2c5f8a;
}

.warehouse-sim-container .warehouse-sim-briefing h3 {
    color: #1a3a5c;
    margin-top: 0;
    font-size: 1.2rem;
}

.warehouse-sim-container .warehouse-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.06);
}

.warehouse-sim-container .warehouse-sim-controls h3 {
    color: #1a3a5c;
    margin-top: 0;
    font-size: 1.2rem;
}

.warehouse-sim-container .warehouse-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 20px;
    margin-bottom: 24px;
}

.warehouse-sim-container .warehouse-sim-chart-wrapper {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.06);
    min-height: 280px;
}

.warehouse-sim-container .warehouse-sim-chart-wrapper h4 {
    color: #1a3a5c;
    margin-top: 0;
    font-size: 1rem;
}

.warehouse-sim-container .warehouse-sim-history {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.06);
}

.warehouse-sim-container .warehouse-sim-history h4 {
    color: #1a3a5c;
    margin-top: 0;
}

.warehouse-sim-container .form-group {
    margin-bottom: 14px;
}

.warehouse-sim-container .form-group label {
    font-weight: 600;
    color: #333;
    font-size: 0.9rem;
}

.warehouse-sim-container .alert-event {
    background: #fff3cd;
    border: 1px solid #ffc107;
    border-radius: 8px;
    padding: 12px 16px;
    margin-top: 14px;
    font-size: 0.9rem;
}

@media (max-width: 768px) {
    .warehouse-sim-container .warehouse-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .warehouse-sim-container .warehouse-sim-charts {
        grid-template-columns: 1fr;
    }
}

