                    decisions[f.id] = (f.id === 'dockDoors' || f.id === 'extraWorkers') ? parseInt(el.value) : parseFloat(el.value);
                } else if (f.type === 'checkbox') {
                    decisions[f.id] = !!el.checked;
                } else {
                    decisions[f.id] = el.value;
                }
            }
        }

        calculateResults(state) {
            var round = state.currentPeriod;
            var d = state.decisions;
            var ds = state.domainState;

            var eventList = RANDOM_EVENTS[round] || [];
            var eventIdx = Math.floor(Math.random() * eventList.length);
            var eventObj = eventList[eventIdx] || null;
            var eventId = eventObj ? eventObj.id : '';
            var eventKey = eventObj ? eventObj.key : '';
            // Store the i18n key in the log; display layer localizes it.
            ds.eventLog.push({ round: round, id: eventId, key: eventKey });

            var costDelta = 0;
            var speedDelta = 0;
            var accDelta = 0;
            var npsDelta = 0;
            var cashDelta = 0;

            if (round === 1) {
                var storagePct = d.storagePercent || 50;
                var pickPct = d.pickingPercent || 20;
                var packPct = d.packingPercent || 15;
                var returnsPct = d.returnsPercent || 8;
                var docks = d.dockDoors || 3;
                var layout = d.aisleLayout || 'class-based';

                if (layout === 'class-based') {
                    costDelta = -0.10; speedDelta = -3; accDelta = 1.5;
                } else if (layout === 'distributed') {
                    costDelta = -0.05; speedDelta = -1; accDelta = 0.5;
                } else {
                    costDelta = -0.03; speedDelta = -2; accDelta = 1; npsDelta = 1;
                }

                speedDelta -= (docks - 3) * 0.8;
                accDelta += (pickPct > 22) ? 0.5 : -0.3;
                npsDelta += 2;
                cashDelta = -((docks - 3) * 0.05);

                // Zone sizing now has consequences (previously inert decisions).
                // Storage: a balanced ~50% band optimizes flow; extremes hurt.
                if (storagePct >= 48 && storagePct <= 54) { accDelta += 0.4; }
                else if (storagePct < 44 || storagePct > 58) { speedDelta += 1; accDelta -= 0.3; }
                // Packing capacity: more packing/shipping space speeds throughput.
                if (packPct >= 15) { speedDelta -= 0.6; }
                else if (packPct < 12) { speedDelta += 0.6; }
                // Returns area: adequate returns space pays off in service quality.
                if (returnsPct >= 10) { accDelta += 0.3; npsDelta += 0.5; }
                else if (returnsPct < 6) { npsDelta -= 0.5; }

                if (eventId === 'lease') { cashDelta -= 0.5; }
                if (eventId === 'union') { cashDelta -= 0.3; speedDelta += 1; }
                if (eventId === 'rival') { npsDelta -= 1; }
            } else if (round === 2) {
                var auto = d.automationChoice || 'none';
                var labor = d.laborStrategy || 'moderate';
                var funding = d.fundingSource || 'internal';
                var autoCost = 0;
                var tpBoost = 0;

                if (auto === 'robots') { autoCost = 3.5; tpBoost = 40; }
                else if (auto === 'sortation') { autoCost = 2.8; tpBoost = 25; }
                else if (auto === 'pick-to-light') { autoCost = 1.2; tpBoost = 15; }
                else if (auto === 'integrated') { autoCost = 4.0; tpBoost = 35; }

                cashDelta = -autoCost;
                costDelta = -(tpBoost * 0.004);
                speedDelta = -(tpBoost * 0.08);
                accDelta = tpBoost > 0 ? 1.0 : 0;
                ds.throughput = ds.throughput * (1 + tpBoost / 100);

                if (labor === 'heavy-temp') { cashDelta += 0.2; accDelta -= 0.5; }
                else if (labor === 'lean-auto') { cashDelta -= 0.3; accDelta += 0.5; speedDelta -= 0.5; }

                if (funding === 'debt') { cashDelta += autoCost * 0.5; }

                npsDelta = 1;

                if (eventId === 'delay') { speedDelta += 2; cashDelta -= 0.2; }
                if (eventId === 'wms') { cashDelta -= 0.2; }
                if (eventId === 'volume') { npsDelta += 2; cashDelta += 0.5; }
            } else if (round === 3) {
                var demand = d.demandStrategy || 'extend-sla';
                var tempFac = d.tempFacility ? 1.2 : 0;
                var extra = d.extraWorkers || 0;
                var pricing = d.pricingStrategy || 'standard';

                cashDelta = -tempFac - (extra * 0.004);

                if (demand === 'accept-all') {
                    speedDelta = 6; accDelta = -2; npsDelta = -3; costDelta = 0.18; cashDelta += 3.0;
                } else if (demand === 'cap-volume') {
                    speedDelta = 0; accDelta = 0.5; npsDelta = -1; costDelta = -0.05; cashDelta += 1.0;
                } else {
                    speedDelta = 2; accDelta = 0; npsDelta = 1; costDelta = -0.08; cashDelta += 2.0;
                }

                if (d.tempFacility) { speedDelta -= 2; accDelta += 0.5; npsDelta += 1; }
                if (extra > 50) { speedDelta -= 1.5; accDelta -= 0.5; }
                else if (extra > 20) { speedDelta -= 0.5; }

                if (pricing === 'premium-tiered') { cashDelta += 1.5; npsDelta -= 1; }
                else if (pricing === 'discount-extended') { cashDelta -= 0.5; npsDelta += 2; }

                if (eventId === 'tight') { speedDelta += 2; npsDelta -= 2; }
                if (eventId === 'drop40') { cashDelta -= 1.0; npsDelta -= 1; }
                if (eventId === 'carrier') { costDelta += 0.08; npsDelta -= 1; }
            } else if (round === 4) {
                var zoneR = d.zoneRouting ? true : false;
                var sameDay = d.sameDayDelivery ? true : false;
                var tw = d.timeWindows || 'loose';
                var carrier = d.carrierStrategy || 'multi';
                var carbon = d.carbonStrategy || 'none';

                if (zoneR) { cashDelta -= 0.8; costDelta -= 0.12; speedDelta -= 1.5; accDelta += 0.5; }
                if (sameDay) { cashDelta -= 1.5; costDelta += 0.10; speedDelta -= 4; npsDelta += 4; }

                if (tw === 'tight') { npsDelta += 2; costDelta += 0.04; accDelta += 0.3; }
                else if (tw === 'mixed') { npsDelta += 1; costDelta += 0.01; }

                if (carrier === 'consolidate') { costDelta -= 0.08; npsDelta -= 1; }
                else if (carrier === 'multi') { npsDelta += 1; costDelta -= 0.02; }

                if (carbon === 'offset') { cashDelta -= 0.1; npsDelta += 1; }
                else if (carbon === 'ev-fleet') { cashDelta -= 0.8; npsDelta += 2; costDelta -= 0.05; }
                else if (carbon === 'route-only') { costDelta -= 0.03; npsDelta += 0.5; }

                if (eventId === 'misroute') { accDelta -= 1.5; npsDelta -= 2; }
                if (eventId === 'rate') { costDelta += 0.10; }
                if (eventId === 'evdisc') { costDelta -= 0.08; npsDelta += 1; }
            } else if (round === 5) {
                var staffing = d.returnsStaffing || 'combo';
                var refund = d.refundPolicy || 'standard';
                var liq = d.liquidationStrategy || 'basic';
                var fee = d.restockingFee ? true : false;

                if (staffing === 'hire-temp') { cashDelta -= 0.6; costDelta -= 0.08; speedDelta -= 3; }
                else if (staffing === 'outsource') { cashDelta -= 1.0; costDelta -= 0.12; speedDelta -= 2; npsDelta += 1; }
                else { cashDelta -= 0.8; costDelta -= 0.10; speedDelta -= 2.5; }

                if (refund === 'immediate') { npsDelta += 3; cashDelta -= 0.5; }
                else if (refund === 'fast-track') { npsDelta += 1.5; cashDelta -= 0.3; }
                else { npsDelta -= 1; }

                if (liq === 'basic') { cashDelta += 0.3; }
                else if (liq === 'develop') { cashDelta += 0.8; npsDelta += 1; }
                else if (liq === 'premium') { cashDelta += 1.5; npsDelta += 2; costDelta -= 0.03; }

                if (fee) { cashDelta += 0.4; npsDelta -= 2; }

                if (eventId === 'bankrupt') { cashDelta -= 0.5; costDelta += 0.06; }
                if (eventId === 'fraud') { cashDelta -= 0.8; npsDelta -= 2; }
                if (eventId === 'inhouse') { cashDelta -= 1.5; npsDelta -= 2; }
            }

            ds.costPerOrder = Math.max(1.50, ds.costPerOrder + costDelta);
            ds.fulfillmentSpeed = Math.max(6, Math.min(36, ds.fulfillmentSpeed + speedDelta));
            ds.orderAccuracy = Math.max(85, Math.min(99.5, ds.orderAccuracy + accDelta));
            ds.nps = Math.max(0, Math.min(70, ds.nps + npsDelta));
            ds.cash += cashDelta;
            if (typeof ds.scoreProfit !== 'number') ds.scoreProfit = (ds.cumulativeProfit || 0) / 1000000;
            ds.scoreProfit += cashDelta;
            ds.cumulativeProfit += (cashDelta * 1000000);
            // Platform score: the same 0-100 score getPerformanceSummary gives, on the current metrics and the cash impact summed so far
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: this._scoreOf({ costPerOrder: ds.costPerOrder, fulfillmentSpeed: ds.fulfillmentSpeed, orderAccuracy: ds.orderAccuracy, nps: ds.nps }, ds.scoreProfit) });

            ds.costHistory.push(Math.round(ds.costPerOrder * 100) / 100);
            ds.speedHistory.push(Math.round(ds.fulfillmentSpeed * 10) / 10);
            ds.accuracyHistory.push(Math.round(ds.orderAccuracy * 10) / 10);
            ds.npsHistory.push(Math.round(ds.nps));
            ds.cashHistory.push(Math.round(ds.cash * 100) / 100);
            ds.profitHistory.push(Math.round(cashDelta * 100) / 100);

            var self = this;
            if (typeof setTimeout === 'function') {
                setTimeout(function() {
                    self._updateBriefing(window.mySimulation.state);
                    self._renderDecisionsPanel(window.mySimulation.state);
                }, 500);
            }

            return {
                period: round,
                costPerOrder: ds.costPerOrder,
                fulfillmentSpeed: ds.fulfillmentSpeed,
                orderAccuracy: ds.orderAccuracy,
                nps: ds.nps,
                cash: ds.cash,
                roundProfit: cashDelta,
                randomEvent: eventKey ? this._t(eventKey) : '',
                randomEventId: eventId
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + v.toFixed(1) + 'M'; });
            uiManager.bind('costDisplay', 'domainState.costPerOrder',
                function(v) { return '$' + v.toFixed(2); });
            uiManager.bind('speedDisplay', 'domainState.fulfillmentSpeed',
                function(v) { return Math.round(v) + ' hrs'; });
            uiManager.bind('accuracyDisplay', 'domainState.orderAccuracy',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('npsDisplay', 'domainState.nps',
                function(v) { return Math.round(v).toString(); });
            uiManager.bind('profitDisplay', 'domainState.cumulativeProfit',
                function(v) { return '$' + (v / 1000000).toFixed(2) + 'M'; });
        }

