        _scoreOf(lastResult, totalProfit) {
            var score = 50;
            var finalCost = lastResult.costPerOrder || 2.40;
            if (finalCost <= 2.00) score += 15;
            else if (finalCost <= 2.20) score += 10;
            else if (finalCost <= 2.40) score += 5;
            else score -= 5;

            var finalSpeed = lastResult.fulfillmentSpeed || 22;
            if (finalSpeed <= 12) score += 15;
            else if (finalSpeed <= 16) score += 10;
            else if (finalSpeed <= 20) score += 5;
            else score -= 5;

            var finalAcc = lastResult.orderAccuracy || 94;
            if (finalAcc >= 98) score += 10;
            else if (finalAcc >= 96) score += 5;
            else score -= 5;

            var finalNps = lastResult.nps || 35;
            if (finalNps >= 50) score += 10;
            else if (finalNps >= 45) score += 5;
            else if (finalNps < 35) score -= 5;

            if (totalProfit > 0) score += Math.min(10, totalProfit * 3);
            else score += Math.max(-10, totalProfit * 2);

            return Math.max(0, Math.min(100, Math.round(score)));
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var totalProfit = 0;
            var lastResult = null;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results;
                if (r) { totalProfit += (r.roundProfit || 0); lastResult = r; }
            }
            if (!lastResult) return {};

            var score = this._scoreOf(lastResult, totalProfit);
            var finalCost = lastResult.costPerOrder || 2.40;
            var finalSpeed = lastResult.fulfillmentSpeed || 22;
            var finalAcc = lastResult.orderAccuracy || 94;
            var finalNps = lastResult.nps || 35;

            // Canonical (language-independent) performance key for grading/reporting.
            var levelKey = 'perf_needs';
            if (score >= 80) levelKey = 'perf_excellent';
            else if (score >= 60) levelKey = 'perf_good';
            else if (score >= 40) levelKey = 'perf_developing';
            var levelCanonical = { perf_needs: 'Needs Improvement', perf_excellent: 'Excellent', perf_good: 'Good', perf_developing: 'Developing' }[levelKey];

            var insightKeys = [];
            if (finalCost <= 2.10) insightKeys.push('ins_cost_strong');
            if (finalCost > 2.40) insightKeys.push('ins_cost_high');
            if (finalSpeed <= 14) insightKeys.push('ins_speed_strong');
            if (finalSpeed > 20) insightKeys.push('ins_speed_slow');
            if (finalAcc >= 98) insightKeys.push('ins_acc_strong');
            if (finalNps >= 50) insightKeys.push('ins_nps_strong');
            if (finalNps < 35) insightKeys.push('ins_nps_low');
            if (totalProfit > 2) insightKeys.push('ins_cash_strong');
            if (totalProfit < -3) insightKeys.push('ins_cash_heavy');

            var self = this;
            var insights = insightKeys.map(function(k) { return self._t(k); });

            return {
                score: score,
                performance: (self._t(levelKey) !== levelKey) ? self._t(levelKey) : levelCanonical,
                performanceKey: levelKey,
                totalProfit: Math.round(totalProfit * 100) / 100,
                finalCost: Math.round(finalCost * 100) / 100,
                finalSpeed: Math.round(finalSpeed * 10) / 10,
                finalAccuracy: Math.round(finalAcc * 10) / 10,
                finalNps: finalNps,
                insightKeys: insightKeys,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var cost = state.domainState.costPerOrder;
            var speed = state.domainState.fulfillmentSpeed;
            var nps = state.domainState.nps;
            var acc = state.domainState.orderAccuracy;

            if (cost > 2.50) return this._t('hint_high_cost');
            if (speed > 24) return this._t('hint_slow');
            if (nps < 30) return this._t('hint_low_nps');
            if (acc < 92) return this._t('hint_low_accuracy');
            if (state.domainState.cash < 5) return this._t('hint_low_cash');
            return this._t('hint_good');
        }

