        _updateBriefing(state) {
            var round = state.currentPeriod || 1;
            var briefEl = document.getElementById('briefingText');
            if (!briefEl) return;

            if (round > ROUND_KEYS.length) {
                var summary = this.getPerformanceSummary(state.history || []);
                var perfLabel = summary.performanceKey ? this._t(summary.performanceKey) : (summary.performance || 'N/A');
                var html = '<h5>' + this._t('complete_title') + '</h5>';
                html += '<p><strong>' + this._t('lbl_final_score') + ':</strong> ' + (summary.score || 0) + '/100 (' + perfLabel + ')</p>';
                html += '<p><strong>' + this._t('lbl_final_cost') + ':</strong> $' + (summary.finalCost || 0).toFixed(2) + '</p>';
                html += '<p><strong>' + this._t('lbl_speed') + ':</strong> ' + Math.round(summary.finalSpeed || 0) + ' ' + this._t('lbl_hours') + '</p>';
                html += '<p><strong>' + this._t('lbl_accuracy') + ':</strong> ' + (summary.finalAccuracy || 0).toFixed(1) + '%</p>';
                html += '<p><strong>' + this._t('lbl_nps') + ':</strong> ' + Math.round(summary.finalNps || 0) + '</p>';
                html += '<p><strong>' + this._t('lbl_total_cash') + ':</strong> $' + (summary.totalProfit || 0).toFixed(2) + 'M</p>';
                if (summary.insights && summary.insights.length > 0) {
                    html += '<hr><strong>' + this._t('lbl_insights') + ':</strong><br>';
                    for (var k = 0; k < summary.insights.length; k++) {
                        html += '• ' + summary.insights[k] + '<br>';
                    }
                }
                briefEl.innerHTML = html;
                var btn = document.getElementById('nextPeriodBtn');
                if (btn) btn.disabled = true;
                var dp = document.getElementById('decisionsPanel');
                if (dp) dp.innerHTML = '';
                return;
            }

            var idx = Math.min(round - 1, ROUND_KEYS.length - 1);
            var roundData = ROUND_KEYS[idx];
            var briefHtml = '<h5>' + this._t(roundData.titleKey) + '</h5>';
            briefHtml += '<p>' + this._t(roundData.descKey) + '</p>';
            briefHtml += '<hr>' + this._t(roundData.briefKey);

            var events = state.domainState ? state.domainState.eventLog : [];
            if (events && events.length > 0) {
                var lastEvent = events[events.length - 1];
                var evText = (lastEvent && lastEvent.key) ? this._t(lastEvent.key) : (lastEvent || '');
                briefHtml += '<div class="alert-event"><strong>' + this._t('latest_event') + ':</strong> ' + evText + '</div>';
            }

            briefEl.innerHTML = briefHtml;
        }

        _renderDecisionsPanel(state) {
            var round = state.currentPeriod || 1;
            var panel = document.getElementById('decisionsPanel');
            if (!panel) return;
            if (round > ROUND_KEYS.length) { panel.innerHTML = ''; return; }

            var fields = DECISION_FIELDS[round] || [];
            var html = '';
            for (var i = 0; i < fields.length; i++) {
                var f = fields[i];
                if (f.type === 'number') {
                    html += '<div class="form-group"><label for="' + f.id + '">' + this._t(f.labelKey) + '</label>';
                    html += '<input type="number" class="form-control" id="' + f.id + '" min="' + f.min + '" max="' + f.max + '" value="' + f.value + '" step="' + f.step + '">';
                    if (f.helpKey) { html += '<small class="form-text text-muted">' + this._t(f.helpKey) + '</small>'; }
                    html += '</div>';
                } else if (f.type === 'select') {
                    html += '<div class="form-group"><label for="' + f.id + '">' + this._t(f.labelKey) + '</label>';
                    html += '<select class="form-control" id="' + f.id + '">';
                    for (var j = 0; j < f.options.length; j++) {
                        html += '<option value="' + f.options[j].v + '">' + this._t(f.options[j].key) + '</option>';
                    }
                    html += '</select></div>';
                } else if (f.type === 'checkbox') {
                    html += '<div class="form-check mb-2"><input type="checkbox" class="form-check-input" id="' + f.id + '">';
                    html += '<label class="form-check-label" for="' + f.id + '">' + this._t(f.labelKey) + '</label></div>';
                }
            }
            panel.innerHTML = html;
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new WarehouseOpsAdapter(), {
            simulationType: 'warehouse_ops_199',
            maxPeriods: 5,
            autoSaveInterval: 30000
        });
    });

